.root { position: relative; display: inline-flex; flex: none; vertical-align: middle; }

/* The trigger anchors the menu, so it answers hover and press with color, never with scale. */
.trigger { --presence-surface: var(--user-menu-surface, var(--surface)); position: relative; display: inline-flex; height: 40px; flex: none; align-items: center; gap: var(--space-2); margin: 0; padding: 4px; border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--foreground); font: inherit; font-family: var(--font-body); font-size: var(--text-sm); letter-spacing: var(--tracking-body); cursor: pointer; -webkit-tap-highlight-color: transparent; transition: background-color var(--duration-fast) var(--ease-standard); }
.trigger[data-name] { padding-right: 10px; }
@media (hover: hover) and (pointer: fine) { .trigger:hover { --presence-surface: var(--surface-muted); background: var(--surface-muted); } }
.trigger[data-state="open"] { --presence-surface: var(--surface-muted); background: var(--surface-muted); }
.trigger:active { --presence-surface: color-mix(in oklch, var(--surface-muted), var(--foreground) 8%); background: color-mix(in oklch, var(--surface-muted), var(--foreground) 8%); }
.triggerName { max-width: 11rem; overflow: hidden; font-weight: 500; line-height: 1; text-overflow: ellipsis; white-space: nowrap; }
.chevron { flex: none; margin-left: -2px; color: var(--text-muted); transition: transform var(--duration-spring) var(--ease-spring), color var(--duration-fast) var(--ease-standard); }
.trigger:hover .chevron, .trigger[data-state="open"] .chevron { color: var(--foreground); }
.trigger[data-state="open"] .chevron { transform: rotate(180deg); }
@media (max-width: 639px) {
  .trigger[data-name] { padding-right: 4px; }
  .triggerName, .chevron { display: none; }
}

.face { position: relative; display: inline-grid; width: var(--face-size); height: var(--face-size); flex: none; }
.face[data-size="sm"] { --face-size: 32px; --dot-size: 11px; }
.face[data-size="md"] { --face-size: 40px; --dot-size: 12px; }
.portrait { display: block; width: 100%; height: 100%; border-radius: var(--radius-pill); background: var(--surface-muted); object-fit: cover; object-position: 50% 15%; outline: 1px solid color-mix(in oklch, var(--foreground) 9%, transparent); outline-offset: -1px; user-select: none; }
.initials { display: grid; place-items: center; color: var(--text-secondary); font-size: calc(var(--face-size) * .36); font-weight: 500; line-height: 1; }
.face .dot { position: absolute; right: -1px; bottom: -1px; box-shadow: 0 0 0 2px var(--presence-surface, var(--surface)); }

/* One mark, three shapes: solid for available, a bar for busy, a ring for away. Color and shape change together, so status never rests on color alone. */
.dot { --dot-color: var(--success); position: relative; display: inline-block; width: var(--dot-size, 10px); height: var(--dot-size, 10px); flex: none; border-radius: var(--radius-pill); background: var(--dot-color); transition: background-color var(--duration-standard) var(--ease-standard), box-shadow var(--duration-fast) var(--ease-standard); }
.dot::before, .dot::after { content: ""; position: absolute; inset: 0; margin: auto; background: var(--presence-surface, var(--surface)); transition: transform var(--duration-spring) var(--ease-spring), background-color var(--duration-fast) var(--ease-standard); }
.dot::before { width: 46%; height: 46%; border-radius: var(--radius-pill); transform: scale(0); }
.dot::after { width: 58%; height: 22%; min-height: 1.5px; border-radius: 1px; transform: scaleX(0); }
.dot[data-status="busy"] { --dot-color: var(--danger); }
.dot[data-status="busy"]::after { transform: scaleX(1); }
.dot[data-status="away"] { --dot-color: var(--warning); }
.dot[data-status="away"]::before, .dot[data-status="offline"]::before { transform: scale(1); }
.dot[data-status="offline"] { --dot-color: var(--text-muted); }

/* The panel scales out of the avatar it belongs to; the component sets the origin once it is placed. */
.panel { --presence-surface: var(--surface-raised); --row: 40px; --inset: 6px; position: fixed; top: 0; left: 0; z-index: 60; box-sizing: border-box; width: 17rem; max-width: calc(100vw - 24px); padding: var(--inset); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface-raised); box-shadow: var(--shadow-floating); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); line-height: var(--leading-body); text-align: left; outline: none; transform-origin: var(--origin-x, 100%) var(--origin-y, 0px); }
.panel[data-inline] { position: absolute; top: calc(100% + 8px); left: auto; }
.panel[data-inline][data-align="end"] { right: 0; }
.panel[data-inline][data-align="start"] { left: 0; }
.panel[data-inline][data-align="center"] { left: 50%; margin-left: -8.5rem; }

.header { display: flex; align-items: center; gap: var(--space-3); padding: 8px 8px 10px; }
.identity { display: grid; min-width: 0; flex: 1; gap: 1px; }
.nameRow { display: flex; min-width: 0; align-items: center; gap: var(--space-2); }
.name { overflow: hidden; color: var(--foreground); font-size: var(--text-sm); font-weight: 500; text-overflow: ellipsis; white-space: nowrap; }
.plan { display: inline-flex; flex: none; align-items: center; height: 18px; padding: 0 7px; border-radius: var(--radius-pill); background: var(--accent-subtle); color: var(--accent-strong); font-size: 11px; font-weight: 500; line-height: 1; }
.email { overflow: hidden; color: var(--text-muted); font-size: var(--text-xs); text-overflow: ellipsis; white-space: nowrap; }

.list { position: relative; }
.separator { height: 1px; margin: var(--inset) calc(var(--inset) * -1); background: var(--border-subtle); }

/* One highlight follows the pointer and the keyboard. It is the only hover treatment in the menu. */
.highlight { position: absolute; top: 0; right: 0; left: 0; border-radius: calc(var(--radius-panel) - var(--inset)); background: var(--accent-subtle); opacity: 0; pointer-events: none; }
.highlight[data-tone="danger"] { background: color-mix(in oklch, var(--danger) 11%, transparent); }

.item { position: relative; display: flex; width: 100%; height: var(--row); box-sizing: border-box; align-items: center; gap: var(--space-3); margin: 0; padding: 0 12px; border: 0; border-radius: calc(var(--radius-panel) - var(--inset)); background: transparent; color: var(--foreground); font: inherit; font-size: var(--text-sm); text-align: left; cursor: pointer; outline: none; user-select: none; -webkit-tap-highlight-color: transparent; transition: color var(--duration-fast) var(--ease-standard); }
.icon { display: inline-grid; width: 16px; flex: none; place-items: center; color: var(--text-secondary); transition: color var(--duration-fast) var(--ease-standard); }
.item:focus .icon { color: var(--accent-strong); }
.itemLabel { position: relative; display: inline-flex; min-width: 0; flex: 1; }
.rise { display: inline-block; white-space: nowrap; }
.item[data-tone="danger"], .item[data-tone="danger"] .icon { color: color-mix(in oklch, var(--danger) 58%, var(--text-secondary)); }
.item[data-tone="danger"]:focus, .item[data-tone="danger"]:focus .icon { color: var(--danger); }
@media (hover: none) { .item:active { background: var(--surface-muted); } }

.keys { display: inline-flex; flex: none; align-items: center; gap: 1px; margin-left: auto; color: var(--text-muted); font-family: var(--font-body); font-size: var(--text-xs); letter-spacing: 0; opacity: .8; font-variant-numeric: tabular-nums; }
.key { display: inline-block; min-width: 1.05em; font: inherit; text-align: center; }

.row { position: relative; display: flex; height: 44px; align-items: center; gap: var(--space-3); padding: 0 6px 0 12px; }
.rowLabel { flex: 1; color: var(--foreground); font-size: var(--text-sm); }
.row .icon .dot { --dot-size: 10px; }
/* The thumb slides under the icons; the group owns the stacking context. */
.segments { --segment: 32px; position: relative; isolation: isolate; display: inline-grid; height: 30px; flex: none; grid-auto-columns: var(--segment); grid-auto-flow: column; padding: 2px; border-radius: var(--radius-pill); background: color-mix(in oklch, var(--foreground) 6%, transparent); }
.thumb { position: absolute; z-index: -1; top: 2px; bottom: 2px; left: 2px; width: var(--segment); border-radius: var(--radius-pill); background: var(--surface-raised); box-shadow: 0 1px 2px oklch(0% 0 0 / .1), 0 0 0 1px var(--border-subtle); transform: translateX(calc(var(--index) * 100%)); transition: transform var(--duration-spring) var(--ease-spring); }
:global([data-theme="dark"]) .thumb { background: color-mix(in oklch, var(--foreground) 20%, var(--surface-raised)); box-shadow: none; }
.segment { display: grid; place-items: center; margin: 0; padding: 0; border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--text-muted); cursor: pointer; outline: none; -webkit-tap-highlight-color: transparent; transition: color var(--duration-fast) var(--ease-standard); }
.segment .dot { --dot-size: 9px; --presence-surface: var(--surface-raised); }
@media (hover: hover) and (pointer: fine) { .segment:hover { color: var(--text-secondary); } }
.segment[aria-checked="true"] { color: var(--foreground); }

.spinner { animation: user-menu-spin .8s linear infinite; }
@keyframes user-menu-spin { to { transform: rotate(360deg); } }

/* Below 640px the same content rises as a bottom sheet with larger rows. */
.scrim { position: fixed; inset: 0; z-index: 70; background: oklch(0% 0 0 / .32); -webkit-tap-highlight-color: transparent; }
.sheet { --row: 48px; --inset: 10px; position: fixed; top: auto; right: 0; bottom: 0; left: 0; z-index: 71; width: auto; max-width: none; max-height: 88dvh; overflow-y: auto; overscroll-behavior: contain; padding: 8px var(--inset) calc(12px + env(safe-area-inset-bottom)); border-bottom: 0; border-radius: var(--radius-panel) var(--radius-panel) 0 0; }
.handle { display: block; width: 36px; height: 5px; margin: 0 auto 10px; border-radius: var(--radius-pill); background: var(--border-strong); cursor: grab; }
.sheet .header { padding: 4px 8px 12px; }
.sheet .item, .sheet .rowLabel { font-size: var(--text-base); }
.sheet .row { height: 56px; }
.sheet .segments { --segment: 44px; height: 38px; }
.sheet .keys { display: none; }

@media (prefers-reduced-motion: reduce) {
  .trigger, .chevron, .dot, .dot::before, .dot::after, .segment, .thumb, .item, .icon { transition: none; }
  .spinner { animation-duration: 2.4s; }
}
